from pathlib import Path
base=Path('/mnt/data/v18work/frontend/static')
index=(base/'index.html').read_text(encoding='utf-8')
# Remove artifacts card block from generator page.
start=index.find('        <div class="artifacts-card">')
if start!=-1:
    end=index.find('        <div class="files-card">', start)
    index=index[:start]+index[end:]
# Add nav to header.
needle='      <div class="live-status"><span class="live-dot"></span> LIVE</div>\n'
nav='''      <nav class="topnav">\n        <a class="nav-link active" href="/">Generate</a>\n        <a class="nav-link" href="/generated">Generated</a>\n      </nav>\n'''
index=index.replace(needle, nav+needle)
# Update subtitle and title.
index=index.replace('<title>Adaptive Crawler</title>','<title>Adaptive Crawler — Generate</title>')
index=index.replace('<h1>Adaptive Crawler</h1>','<h1>Adaptive Crawler</h1>')
index=index.replace('<p>Analyze each host once. Choose the cheapest reliable extraction strategy, then generate its crawler.</p>', '<p>Analyze a page, build its extraction structure, and generate a reusable crawler.</p>')
(base/'index.html').write_text(index,encoding='utf-8')

# Generated management page.
gen='''<!doctype html>\n<html lang="en" dir="ltr">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width,initial-scale=1">\n  <title>Adaptive Crawler — Generated</title>\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Mono:wght@400;700&display=swap" rel="stylesheet">\n  <link rel="stylesheet" href="/static/style.css">\n</head>\n<body>\n  <div class="bg-orb orb-one"></div><div class="bg-orb orb-two"></div>\n  <div class="app-shell">\n    <header class="topbar">\n      <div class="brand"><div class="brand-mark">AC</div><div>\n        <div class="eyebrow">AGENTIC WEB EXTRACTION</div>\n        <h1>Generated</h1>\n        <p>Browse generated crawlers, prompts, structures, source HTML, validation reports, and download complete jobs.</p>\n      </div></div>\n      <nav class="topnav"><a class="nav-link" href="/">Generate</a><a class="nav-link active" href="/generated">Generated</a></nav>\n      <div class="live-status"><span class="live-dot"></span> LIVE</div>\n    </header>\n    <main class="generated-layout">\n      <section class="panel explorer-panel">\n        <div class="panel-heading">\n          <div><span class="step-label">01</span><h2>Generated library</h2></div>\n          <div class="artifact-toolbar"><button id="refreshArtifacts" class="tiny-button">Refresh</button></div>\n        </div>\n        <div class="artifact-path" id="artifactPath">generated/</div>\n        <div id="artifactTree" class="artifact-tree full-height"><div class="artifact-empty">Loading generated artifacts…</div></div>\n      </section>\n      <section class="panel preview-panel">\n        <div class="panel-heading">\n          <div><span class="step-label">02</span><h2 id="previewTitle">Artifact preview</h2></div>\n          <span id="previewMeta" class="micro-copy">Select a file</span>\n        </div>\n        <div class="preview-toolbar">\n          <a id="downloadCurrent" class="artifact-link disabled-link" href="#">Download</a>\n          <a id="downloadFolder" class="artifact-link disabled-link" href="#">Download folder ZIP</a>\n        </div>\n        <div id="previewEmpty" class="preview-empty">Choose a file from the generated library to preview it here.</div>\n        <pre id="previewContent" class="standalone-preview hidden"></pre>\n      </section>\n    </main>\n  </div>\n  <script src="/static/generated.js"></script>\n</body>\n</html>\n'''
(base/'generated.html').write_text(gen,encoding='utf-8')

js='''function escapeHtml(value){return String(value).replace(/[&<>\'\"]/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;","\\'":"&#39;",\"\\\"\":\"&quot;\"}[ch]));}\nfunction $(id){return document.getElementById(id);}\n\nasync function loadArtifacts(){\n  const treeEl=$(\'artifactTree\');\n  try{\n    const r=await fetch(\'/artifacts/tree\'); const payload=await r.json();\n    if(!r.ok) throw new Error(payload.detail||\'Artifact tree failed\');\n    treeEl.innerHTML=\'\';\n    if(!payload.tree?.length){treeEl.innerHTML=\'<div class="artifact-empty">No generated artifacts yet.</div>\';return;}\n    payload.tree.forEach(node=>treeEl.appendChild(renderNode(node,0)));\n  }catch(e){treeEl.innerHTML=`<div class="artifact-empty">${escapeHtml(e.message)}</div>`;}\n}\n\nfunction renderNode(node,level){\n  const wrap=document.createElement(\'div\'); wrap.className=\'artifact-node\';\n  if(node.type===\'folder\'){\n    const head=document.createElement(\'div\'); head.className=\'artifact-row folder-row\';\n    head.style.paddingLeft=`calc(7px + ${level*18}px)`;\n    const hasZip=node.path && node.path.split(\'/\').length>1;\n    head.innerHTML=`<span class="artifact-chevron">▾</span><span class="artifact-icon">▰</span><span class="artifact-name">${escapeHtml(node.name)}</span>${hasZip?`<span class="artifact-actions"><a class="artifact-link" href="/artifacts/zip?path=${encodeURIComponent(node.path)}">ZIP</a></span>`:\'\'}`;\n    const children=document.createElement(\'div\'); children.className=\'artifact-children\';\n    (node.children||[]).forEach(c=>children.appendChild(renderNode(c,level+1)));\n    head.onclick=(e)=>{if(e.target.closest(\'a\'))return;children.classList.toggle(\'collapsed\');head.querySelector(\'.artifact-chevron\').textContent=children.classList.contains(\'collapsed\')?\'▸\':\'▾\';};\n    wrap.append(head,children); return wrap;\n  }\n  const row=document.createElement(\'div\'); row.className=\'artifact-row file-row\'; row.style.paddingLeft=`calc(7px + ${level*18}px)`;\n  const kb=node.size>=1024?`${(node.size/1024).toFixed(1)} KB`:`${node.size} B`;\n  row.innerHTML=`<span class="artifact-icon">▤</span><span class="artifact-name">${escapeHtml(node.name)}</span><span class="artifact-size">${kb}</span><span class="artifact-actions"><button class="artifact-link">Preview</button><a class="artifact-link" href="${node.download}">Download</a></span>`;\n  row.querySelector(\'button\').onclick=()=>preview(node.path,node.name,node.parent_path||null,node.download);\n  wrap.appendChild(row); return wrap;\n}\n\nasync function preview(path,name,parentPath,download){\n  try{\n    const r=await fetch(\'/artifacts/preview?path=\'+encodeURIComponent(path)); const payload=await r.json();\n    if(!r.ok) throw new Error(payload.detail||\'Preview failed\');\n    $(\'previewTitle\').textContent=name; $(\'previewMeta\').textContent=payload.size.toLocaleString()+\' bytes\';\n    $(\'previewContent\').textContent=payload.content; $(\'previewContent\').classList.remove(\'hidden\'); $(\'previewEmpty\').classList.add(\'hidden\');\n    const dl=$(\'downloadCurrent\'); dl.href=download; dl.classList.remove(\'disabled-link\');\n    const folder=parentPath ? \'/artifacts/zip?path=\'+encodeURIComponent(parentPath) : \'#\'; const df=$(\'downloadFolder\'); df.href=folder; df.classList.toggle(\'disabled-link\',!parentPath);\n    $(\'artifactPath\').textContent=path;\n  }catch(e){$(\'previewEmpty\').textContent=e.message;$(\'previewEmpty\').classList.remove(\'hidden\');}\n}\n$(\'refreshArtifacts\').onclick=loadArtifacts; loadArtifacts();\n'''
(base/'generated.js').write_text(js,encoding='utf-8')

# Add /generated route and richer tree metadata for files.
main=Path('/mnt/data/v18work/app/main.py')
ms=main.read_text(encoding='utf-8')
ms=ms.replace("@app.get('/health')\n", "@app.get('/generated')\nasync def generated_page():\n    return FileResponse('frontend/static/generated.html')\n\n\n@app.get('/health')\n")
main.write_text(ms,encoding='utf-8')

# ArtifactStore tree: add parent_path to file nodes to enable folder ZIP from file preview.
art=Path('/mnt/data/v18work/app/artifacts.py')
as_=art.read_text(encoding='utf-8')
old="""                    node = {\n                        \"type\": \"file\",\n                        \"name\": child.name,\n                        \"path\": rel.replace(\\\"\\\\\\\", \\\"/\\\"),\n                        \"size\": child.stat().st_size,\n                        \"download\": f\"/artifacts/download?path={quote(rel.replace(os.sep, '/'))}\",\n                    }\n"""
# find actual tree block if exact mismatch
if old not in as_:
    print('tree block not matched; showing relevant')
else:
    as_=as_.replace(old,old.replace('"download":', '"parent_path": str(Path(rel).parent).replace(\\"\\\\\\", \\\"/\\\"),\n                        "download":'))
art.write_text(as_,encoding='utf-8')
print('patched ui')
